"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import type { FormEvent } from "react";
import Image from "next/image";
import type { LucideIcon } from "lucide-react";
import { ArrowDownToLine, ArrowRight, Bell, Box, Building2, Check, Clock3, Cpu, FileText, HardDrive, LayoutDashboard, LockKeyhole, Menu, Phone, Plus, Printer, Search, Send, ShieldCheck, Wrench, X } from "lucide-react";

type Ticket = { id:string; branch:string; code:string; issue:string; device:string; priority:"High"|"Medium"|"Low"; status:"Open"|"In progress"|"Waiting"|"Resolved"; time:string; submitted_at?:string; resolved_at?:string|null; resolution_seconds?:number|null; person:string; initials:string; computer_ip?:string; contact_phone?:string; user_id?:string; solver_id?:string; resolution_notes?:string; satisfaction?:string|null };
type Repair = { id:number; branch_name:string; device:string; brand_model:string; serial_no:string; reported_problem:string; status:string; received_at:string; submitted_at?:string|null };
type StockItem = { id:number; item_type:string; brand_model:string; serial_no:string; received_at:string; quantity:number; available_quantity:number; condition:string; source:string };
type PortalDocument = { id:number; title:string; category:string; file_name:string; file_size:number; branch_name:string|null; uploaded_by_name:string; uploaded_at:string };
type HeadOfficeItem = { id:number; item:string; date_received:string; received_from:string; brand_model:string; item_serial_no:string; status:string; signature_received:string; where_supplied:string; date_supplied:string; sign_it:string; take_date:string; remarks:string };
type PortalUser = { username:string; name:string; role:"zonal_staff"|"branch_user"; branchName:string|null };
const branchNames:Record<string,string>={"চাঁপাইনবাবগঞ্জ শাখা":"Chapai Branch","রাজশাহী শাখা":"Rajshahi Branch","নওগাঁ শাখা":"Naogaon Branch","নাটোর শাখা":"Natore Branch","বগুড়া শাখা":"Bogura Branch","পাবনা উপশাখা":"Pabna Sub-Branch"};
const issueNames:Record<string,string>={"শাখার LAN নেটওয়ার্ক সংযোগ বিচ্ছিন্ন":"Branch LAN connection is down","HP LaserJet প্রিন্টারে কাগজ আটকে যাচ্ছে":"HP LaserJet printer paper jam","ইমেইলে লগইন করতে পারছেন না":"Unable to sign in to email","স্ক্যানার থেকে PDF তৈরি হচ্ছে না":"Scanner is not creating PDF files","কোর ব্যাংকিং টার্মিনাল ধীরগতিতে চলছে":"Core banking terminal is running slowly","UPS ব্যাটারি ব্যাকআপ থাকছে না":"UPS battery is not holding charge"};
const contactNames:Record<string,string>={"মোঃ রাশেদুল হাসান":"Md. Rashedul Hasan","আফসানা রহমান":"Afsana Rahman","মোঃ সাইফুল ইসলাম":"Md. Saiful Islam","নাজমা খাতুন":"Nazma Khatun","মোঃ ইমরান হোসেন":"Md. Imran Hossain","শারমিন আক্তার":"Sharmin Akter"};
const englishDigits=(text:string)=>text.replace(/[০-৯]/g,d=>"০১২৩৪৫৬৭৮৯".indexOf(d).toString());
const statusLabels:Record<Ticket["status"],string>={Open:"Open", "In progress":"In Progress", Waiting:"Wait for FRSD", Resolved:"Solved"};
const navItems=[{name:"Live Dashboard",icon:LayoutDashboard},{name:"Call & Incident Register",icon:Phone},{name:"Hardware Workshop Log",icon:Wrench},{name:"New Inventory Register",icon:Box},{name:"Requisition & Forms",icon:FileText},{name:"Report/Log Register",icon:Printer}];
const colors=["aqua","gold","coral","sky","mint","lavender"];
const parseSqlDate=(value?:string|null)=>{if(!value)return null;const parsed=new Date(value.includes("T")?value:`${value.replace(" ","T")}Z`);return Number.isNaN(parsed.getTime())?null:parsed};
const formatDuration=(seconds:number|null|undefined)=>{if(seconds==null||!Number.isFinite(seconds))return "—";const total=Math.max(0,Math.floor(seconds));const days=Math.floor(total/86400);const hours=Math.floor(total%86400/3600);const minutes=Math.floor(total%3600/60);const secs=total%60;return `${days}d ${String(hours).padStart(2,"0")}h ${String(minutes).padStart(2,"0")}m ${String(secs).padStart(2,"0")}s`};
const formatSubmitted=(value:string)=>{const parsed=parseSqlDate(value);return parsed?new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Dhaka",dateStyle:"medium",timeStyle:"short"}).format(parsed):englishDigits(value)};
const localSubmitTime=()=>new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Dhaka",dateStyle:"medium",timeStyle:"medium",hour12:true}).format(new Date());
const dhakaDate=()=>new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Dhaka",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
const dateKey=(value:string)=>{if(/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const parsed=parseSqlDate(value);return parsed?new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Dhaka",year:"numeric",month:"2-digit",day:"2-digit"}).format(parsed):value.slice(0,10)};

export default function Home(){
  const [tickets,setTickets]=useState<Ticket[]>([]); const [repairs,setRepairs]=useState<Repair[]>([]); const [stock,setStock]=useState<StockItem[]>([]); const [headOfficeItems,setHeadOfficeItems]=useState<HeadOfficeItem[]>([]); const [documents,setDocuments]=useState<PortalDocument[]>([]); const [uploading,setUploading]=useState(false); const [branches,setBranches]=useState<{code:string;name:string}[]>([]); const [selectedBranch,setSelectedBranch]=useState(""); const [active,setActive]=useState("Live Dashboard"); const [view,setView]=useState<"admin"|"branch">("admin"); const [auth,setAuth]=useState<PortalUser|null>(null); const [authChecked,setAuthChecked]=useState(false); const [query,setQuery]=useState(""); const [filter,setFilter]=useState("All"); const [inventoryFilter,setInventoryFilter]=useState(""); const [ticketModal,setTicketModal]=useState(false); const [submitTime,setSubmitTime]=useState(""); const [clockNow,setClockNow]=useState(Date.now()); const [repairModal,setRepairModal]=useState(false); const [stockModal,setStockModal]=useState(false); const [headOfficeModal,setHeadOfficeModal]=useState(false); const [deployItem,setDeployItem]=useState<HeadOfficeItem|null>(null); const [notificationsOpen,setNotificationsOpen]=useState(false); const [reportKind,setReportKind]=useState<"incidents"|"repairs"|"inventory">("incidents"); const [reportFrom,setReportFrom]=useState(`${dhakaDate().slice(0,7)}-01`); const [reportTo,setReportTo]=useState(dhakaDate()); const [reportReady,setReportReady]=useState(false); const [selected,setSelected]=useState<string|null>(null); const [resolutionNotes,setResolutionNotes]=useState(""); const [feedbackNote,setFeedbackNote]=useState(""); const [notice,setNotice]=useState(""); const [mobileNav,setMobileNav]=useState(false);
  const load=useCallback(()=>{fetch("/api/tickets").then(r=>r.ok?r.json():[]).then((rows:Ticket[])=>setTickets(rows.map(t=>({...t,branch:branchNames[t.branch]??t.branch,issue:issueNames[t.issue]??t.issue,person:contactNames[t.person]??(t.person||"Branch User"),time:englishDigits(t.time||""),initials:t.initials||"IT"})))).catch(()=>{}); fetch("/api/repairs").then(r=>r.ok?r.json():[]).then((rows:Repair[])=>setRepairs(rows)).catch(()=>{}); fetch("/api/documents").then(r=>r.ok?r.json():[]).then((rows:PortalDocument[])=>setDocuments(rows)).catch(()=>{}); if(view==="admin"){fetch("/api/stock").then(r=>r.ok?r.json():{items:[]}).then((data:{items:StockItem[]})=>setStock(data.items||[])).catch(()=>{});fetch("/api/head-office-inventory").then(r=>r.ok?r.json():[]).then((rows:HeadOfficeItem[])=>setHeadOfficeItems(rows)).catch(()=>{});}},[view]);
  useEffect(()=>{fetch("/api/auth/session").then(r=>r.ok?r.json():{user:null}).then(d=>{setAuth(d.user);setView(d.user?.role==="branch_user"?"branch":"admin");setAuthChecked(true)}).catch(()=>setAuthChecked(true));},[]);
  useEffect(()=>{fetch("/api/branches").then(r=>r.ok?r.json():[]).then((rows:{code:string;name:string}[])=>{setBranches(rows);setSelectedBranch(rows[0]?.name||"")}).catch(()=>setBranches([]));},[]);
  useEffect(()=>{if(auth)load();},[auth,load]);
  useEffect(()=>{if(!auth)return;const timer=setInterval(load,15000);return()=>clearInterval(timer);},[auth,load]);
  useEffect(()=>{if(!auth||(view!=="admin"&&!ticketModal&&active!=="Forward Hardware to Zonal IT"))return;const timer=setInterval(()=>{setClockNow(Date.now());if(ticketModal||repairModal||headOfficeModal||(view==="branch"&&active==="Forward Hardware to Zonal IT"))setSubmitTime(localSubmitTime())},1000);return()=>clearInterval(timer);},[auth,view,ticketModal,repairModal,headOfficeModal,active]);
  const selectedTicket=tickets.find(t=>t.id===selected);
  const pendingTickets=tickets.filter(ticket=>ticket.status!=="Resolved");
  const pendingRepairs=repairs.filter(repair=>!["Solved","Returned to Branch","Sent to Head Office"].includes(repair.status));
  const pendingCount=pendingTickets.length+pendingRepairs.length;
  const visible=useMemo(()=>tickets.filter(t=>(filter==="All"||t.status===filter)&&`${t.id} ${t.branch} ${t.issue} ${t.device}`.toLowerCase().includes(query.toLowerCase())),[tickets,filter,query]);
  const inventoryAtZonal=headOfficeItems.filter(item=>!item.where_supplied&&!['Issued to Branch','In Use'].includes(item.status)).length;
  const inventoryDeployed=headOfficeItems.length-inventoryAtZonal;
  const inventoryGroups=Object.values(headOfficeItems.reduce<Record<string,{name:string;total:number;available:number;brands:Set<string>}>>((groups,item)=>{const key=item.item.trim()||"Unnamed item";const atZonal=!item.where_supplied&&!['Issued to Branch','In Use'].includes(item.status);const group=groups[key]??{name:key,total:0,available:0,brands:new Set<string>()};group.total+=1;if(atZonal)group.available+=1;if(item.brand_model)group.brands.add(item.brand_model);groups[key]=group;return groups;},{}));
  const visibleInventory=headOfficeItems.filter(item=>!inventoryFilter||item.item.trim()===inventoryFilter);
  const counts={total:tickets.length,open:tickets.filter(t=>t.status==="Open").length,waiting:tickets.filter(t=>t.status==="Waiting").length,repairs:repairs.length,solvedRepairs:repairs.filter(r=>r.status==="Solved").length,inRepair:repairs.filter(r=>r.status==="In Repair").length,buffer:stock.reduce((sum,item)=>sum+item.available_quantity,0),deployed:stock.reduce((sum,item)=>sum+item.quantity-item.available_quantity,0)};
  const flash=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2800);};
  const openTicketForm=()=>{setSubmitTime(localSubmitTime());setSelectedBranch(auth?.branchName||branches[0]?.name||"");setTicketModal(true)};
  const openReceiveHardware=()=>{setSubmitTime(localSubmitTime());setSelectedBranch(branches[0]?.name||"");setRepairModal(true)};
  const openHeadOfficeIntake=()=>{setSubmitTime(localSubmitTime());setHeadOfficeModal(true)};
  const elapsedFor=(ticket:Ticket)=>{if(ticket.resolution_seconds!=null)return ticket.resolution_seconds;const resolved=parseSqlDate(ticket.resolved_at);if(ticket.status==="Resolved"&&resolved){const started=parseSqlDate(ticket.submitted_at||ticket.time);return started?Math.max(0,Math.floor((resolved.getTime()-started.getTime())/1000)):null;}if(ticket.status==="Resolved")return null;const started=parseSqlDate(ticket.submitted_at||ticket.time);return started?Math.max(0,Math.floor((clockNow-started.getTime())/1000)):null;};
  const saveTicket=async(data:FormData)=>{const branch=String(data.get("branch")||auth?.branchName||"");const loginId=String(data.get("loginId")||"");const issue=String(data.get("issue")||"");const problemType=String(data.get("problemType")||"Computer / Terminal");const computerIp=String(data.get("computerIp")||"");const contactPhone=String(data.get("contactPhone")||"");const r=await fetch("/api/tickets",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({branch,loginId,issue,problemType,computerIp,contactPhone})});if(!r.ok){flash("Could not save the incident.");return;}setTicketModal(false);load();flash(view==="admin"?"Phone call incident logged successfully.":"Problem submitted to Zonal IT.");};
  const saveRepair=async(data:FormData)=>{const r=await fetch("/api/repairs",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(data.entries()))}); if(!r.ok){flash("Could not save the hardware record.");return;} setRepairModal(false); load(); flash("Hardware received and added to the workshop log.");};
  const saveHeadOfficeItem=async(data:FormData)=>{const payload=Object.fromEntries(data.entries());const r=await fetch("/api/head-office-inventory",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const result=await r.json().catch(()=>({}));if(!r.ok){flash(result.error||"Could not save the Head Office item.");return;}setHeadOfficeModal(false);load();flash("Head Office item received and added to its inventory ledger.");};
  const deployHeadOfficeItem=async(data:FormData)=>{if(!deployItem)return;const payload={id:deployItem.id,where_supplied:String(data.get("where_supplied")||""),sign_it:String(data.get("sign_it")||""),take_date:String(data.get("take_date")||""),remarks:String(data.get("remarks")||"")};const r=await fetch("/api/head-office-inventory",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const result=await r.json().catch(()=>({}));if(!r.ok){flash(result.error||"Could not deploy this inventory item.");return;}setDeployItem(null);load();flash("Inventory item deployed to the selected branch.");};
  const issueStock=async(data:FormData)=>{const r=await fetch("/api/stock",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(data.entries()))});if(!r.ok){const error=await r.json().catch(()=>null);flash(error?.error||"Could not issue this stock item.");return;}setStockModal(false);load();flash("Emergency replacement issued and recorded.");};
  const updateTicket=async(id:string,status:Ticket["status"])=>{const r=await fetch("/api/tickets",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,status,notes:resolutionNotes})});if(r.ok){setSelected(null);setResolutionNotes("");load();flash(status==="Resolved"?"Incident marked solved.":"Incident status updated.");}};
  const submitFeedback=async(id:string,satisfied:boolean)=>{const r=await fetch("/api/tickets/feedback",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,satisfied,note:feedbackNote})});const data=await r.json().catch(()=>({}));if(!r.ok){flash(data.error||"Could not submit feedback.");return;}setFeedbackNote("");load();flash("Thank you for your feedback.");};
  const updateRepair=async(id:number,status:string)=>{const r=await fetch("/api/repairs",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,status})});if(r.ok){load();flash("Workshop record updated.");}};
  const forwardHardware=async(data:FormData)=>{const r=await fetch("/api/repairs",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(data.entries()))});if(!r.ok){flash("Could not forward the hardware record.");return;}load();flash("Hardware forwarding submitted to Zonal IT.");};
  const uploadRequisition=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const form=event.currentTarget;const body=new FormData(form);setUploading(true);try{const response=await fetch("/api/documents",{method:"POST",body});const result=await response.json().catch(()=>({}));if(!response.ok){flash(result.error||"Could not upload the requisition.");return;}form.reset();await load();flash("Requisition uploaded and submitted to Zonal IT.");}catch{flash("Could not reach the portal server.");}finally{setUploading(false);}};
  const withinRange=(value:string|undefined|null)=>{if(!value)return false;const key=dateKey(value);return key>=reportFrom&&key<=reportTo;};
  const reportTickets=tickets.filter(t=>withinRange(t.submitted_at||t.time));
  const reportRepairs=repairs.filter(r=>withinRange(r.submitted_at||r.received_at));
  const reportInventory=headOfficeItems.filter(item=>withinRange(item.date_received));
  const exportSelectedReport=()=>{const quote=(value:unknown)=>`"${String(value??"").replaceAll('"','""')}"`;let headers:string[]=[];let rows:string[][]=[];let filename="";if(reportKind==="incidents"){headers=["Ticket","User ID","Branch","Problem Type","Problem","Submit time","Status","Solver ID","Time to solve"];rows=reportTickets.map(t=>[t.id,t.user_id||"—",t.branch,t.device,t.issue,formatSubmitted(t.submitted_at||t.time),statusLabels[t.status],t.solver_id||"—",formatDuration(elapsedFor(t))]);filename="incident-problem-register";}else if(reportKind==="repairs"){headers=["Record ID","Branch","Device type","Brand & model","Serial number","Reported problem","Status","Received time"];rows=reportRepairs.map(r=>[String(r.id),branchNames[r.branch_name]||r.branch_name,r.device,r.brand_model,r.serial_no,r.reported_problem,r.status,formatSubmitted(r.submitted_at||r.received_at)]);filename="repair-hardware-register";}else{headers=["Item","Date Received","Received From","Brand & Model","SL No. of Item","Status","Signature Received","Where Supplied","Date Supplied","Sign IT","Take Date","Remarks"];rows=reportInventory.map(i=>[i.item,formatSubmitted(i.date_received),i.received_from,i.brand_model,i.item_serial_no,i.status,i.signature_received,i.where_supplied,i.date_supplied,i.sign_it,i.take_date,i.remarks]);filename="new-inventory-register";}const blob=new Blob(["\uFEFF"+[headers,...rows].map(row=>row.map(quote).join(",")).join("\r\n")],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const anchor=document.createElement("a");anchor.href=url;anchor.download=`${filename}-${reportFrom}-to-${reportTo}.csv`;anchor.click();URL.revokeObjectURL(url);};
  const logout=async()=>{await fetch("/api/auth/logout",{method:"POST"});setAuth(null);setTickets([]);setRepairs([]);setStock([]);};
  const title=view==="branch"?"Branch User Portal":active;
  const onDashboard=active==="Live Dashboard";
  const onTickets=active==="Call & Incident Register"||onDashboard;
  const onRepairs=active==="Hardware Workshop Log"||onDashboard;
  const onInventory=active==="New Inventory Register";
  const openNav=(name:string)=>{setActive(name);if(name==="Forward Hardware to Zonal IT")setSubmitTime(localSubmitTime());setMobileNav(false)};

  if(!authChecked)return <main className="portal login-wait">Loading secure portal…</main>;
  if(!auth)return <LoginScreen onLogin={(user)=>{setAuth(user);setView(user.role==="branch_user"?"branch":"admin")}}/>;
  const allowedNav=view==="branch"?[{name:"Call & Incident Register",icon:Phone},{name:"Forward Hardware to Zonal IT",icon:HardDrive},{name:"Requisition & Forms",icon:FileText}]:navItems;
  return <main className="portal">
    <div className="utility-bar"><span className="helpline">HELPLINE</span><span><i className="pin-dot"/> Rajshahi Zonal IT: IP Phone 737</span><b className="utility-sep">|</b><span><Phone size={12}/> Mobile: 01755551781</span><b className="utility-sep">|</b><span>✉ it.rajshahizone@islamibankbd.com</span><div className="view-switch"><small>{view==="admin"?"ZONAL IT":"BRANCH USER"}</small><button className="on">{view==="branch"?auth.branchName:auth.name}</button><button onClick={logout}>Sign out</button></div></div>
    <header className="masthead"><button className="mobile-menu" onClick={()=>setMobileNav(true)}><Menu size={21}/></button><div className="bank-brand"><div className="emblem"><Image src="/brand/islami-bank-emblem.png" alt="Islami Bank emblem" width={39} height={39}/></div><div><strong>Islami Bank Bangladesh PLC</strong><small>Zonal IT Task &amp; Operational Management Portal</small></div><span className="zone-pill">RAJSHAHI ZONE</span></div><div className="mast-actions"><div className="notification-wrap"><button className="bell" aria-label="Notifications" aria-expanded={notificationsOpen} onClick={()=>setNotificationsOpen(open=>!open)}><Bell size={19}/>{pendingCount>0&&<b>{pendingCount}</b>}</button>{notificationsOpen&&<section className="notification-panel"><div className="notification-head"><b>Pending Notifications</b><span>{pendingCount}</span></div>{pendingTickets.length>0&&<><h3>Open IT Problems</h3>{pendingTickets.slice(0,10).map(ticket=><button className="notification-item" key={ticket.id} onClick={()=>{setSelected(ticket.id);setNotificationsOpen(false)}}><span className="notification-dot problem"/><span><b>{ticket.branch} · {ticket.id}</b><small>{ticket.issue} · {statusLabels[ticket.status]}</small></span></button>)}</>}{pendingRepairs.length>0&&<><h3>Pending Hardware</h3>{pendingRepairs.slice(0,10).map(repair=><button className="notification-item" key={repair.id} onClick={()=>{openNav(view==="branch"?"Forward Hardware to Zonal IT":"Hardware Workshop Log");setNotificationsOpen(false)}}><span className="notification-dot hardware"/><span><b>{repair.branch_name} · {repair.device}</b><small>{repair.brand_model||repair.serial_no||"Hardware follow-up"} · {repair.status}</small></span></button>)}</>}{pendingCount===0&&<div className="notification-empty">No pending problems or hardware tasks.</div>}</section>}</div></div></header>
    <aside className={`left-nav ${mobileNav?"show":""}`}><div className="nav-caption">PORTAL NAVIGATION</div>{allowedNav.map(n=>{const Icon=n.icon as LucideIcon;return <button key={n.name} title={n.name} onClick={()=>openNav(n.name)} className={`side-link ${active===n.name?"active":""}`}><Icon size={16}/><span>{n.name}</span></button>})}<div className="office-meta"><b>{view==="branch"?auth.branchName:"Rajshahi Zonal Office"}</b><span>Islami Bank Bangladesh PLC</span><small>Local Server: <strong>Online</strong></small><time>06-11-2026</time></div></aside>{mobileNav&&<button className="nav-scrim" onClick={()=>setMobileNav(false)} aria-label="Close navigation"/>}
    <section className="portal-main">
      <div className="page-heading"><div><div className="heading-line"><h1>{onDashboard?(view==="branch"?"Branch Support Portal":"Zonal IT Operations Overview"):title}</h1>{view==="branch"&&<span className="monitored">{auth.branchName}</span>}</div><p>{view==="branch"?"Submit an IT support request and track its progress.":"Live tracking of incidents, repair hardware, and Head Office inventory."}</p></div><div className="heading-actions">{view==="admin"&&active==="Report/Log Register"&&<div className="register-nav">{[{id:"incidents",label:"Incident or Problem Register",icon:Phone},{id:"repairs",label:"Repair Hardware Register",icon:Wrench},{id:"inventory",label:"New Inventory Register",icon:Box}].map(item=>{const Icon=item.icon;return <button key={item.id} className={reportKind===item.id?"selected":""} onClick={()=>{setReportKind(item.id as typeof reportKind);setReportReady(false)}}><Icon size={14}/>{item.label}</button>})}</div>}{view==="admin"&&(active==="Live Dashboard"||active==="Call & Incident Register")&&<button className="btn-navy" onClick={openTicketForm}><Plus size={15}/> Log Phone Call Incident</button>}{view==="admin"&&(active==="Live Dashboard"||active==="Hardware Workshop Log")&&<button className="btn-coral" onClick={openReceiveHardware}><Plus size={15}/> Receive Hardware</button>}{view==="admin"&&active==="New Inventory Register"&&<button className="btn-coral" onClick={openHeadOfficeIntake}><Plus size={15}/> Receive from Head office</button>}{view==="admin"&&active==="Requisition & Forms"&&<button className="btn-navy" onClick={()=>document.querySelector(".requisition-panel")?.scrollIntoView({behavior:"smooth",block:"center"})}><ArrowDownToLine size={15}/> Download and submit Requisition</button>}{view==="branch"&&active==="Requisition & Forms"&&<button className="btn-navy" onClick={()=>document.querySelector(".requisition-panel")?.scrollIntoView({behavior:"smooth",block:"center"})}><ArrowDownToLine size={15}/> Download and submit Requisition</button>}{view==="branch"&&active!=="Requisition & Forms"&&<button className="btn-navy" onClick={active==="Forward Hardware to Zonal IT"?()=>document.querySelector(".forward-form")?.scrollIntoView({behavior:"smooth",block:"center"}):openTicketForm}><Plus size={15}/> {active==="Forward Hardware to Zonal IT"?"Hardware Submit to Zonal IT":"Problem Submit to Zonal IT"}</button>}</div></div>
      {onDashboard&&view==="admin"&&<div className="metric-grid"><Metric icon={Phone} title="Incident Register" value={String(counts.total)} note="Total logged incidents" color="blue" onClick={()=>openNav("Call & Incident Register")}/><Metric icon={Clock3} title="Pending Incidents" value={String(counts.open+counts.waiting)} note="Open or waiting for support" color="amber" onClick={()=>openNav("Call & Incident Register")}/><Metric icon={Cpu} title="Workshop Hardware" value={`${counts.repairs} Units`} note={`${counts.solvedRepairs} Solved · ${counts.inRepair} In Repair`} color="coral" onClick={()=>openNav("Hardware Workshop Log")}/><Metric icon={Box} title="New Inventory Register" value={`${inventoryAtZonal} Available`} note={`${inventoryDeployed} Deployed · ${headOfficeItems.length} Items`} color="sky" onClick={()=>openNav("New Inventory Register")}/></div>}
      <div className={`operation-grid ${!onDashboard?"single-column":""}`}>
        {onTickets&&<section className="work-panel incident-panel"><div className="work-head"><div><h2>{view==="branch"?"MY BRANCH SUPPORT REQUESTS":"ACTIVE BRANCH SUPPORT QUEUE"}</h2>{!onDashboard&&<p>Phone incidents and portal requests · {visible.length} records</p>}</div><div className="work-head-actions"><button onClick={()=>setFilter(filter==="All"?"Open":"All")}>{filter==="All"?"View Full Register":"Show All"} <ArrowRight size={13}/></button></div></div><div className="queue-controls"><div className="queue-search"><Search size={14}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search branch, ticket or issue..."/></div><div className="status-filters">{["All","Open","In progress","Waiting","Resolved"].map(s=><button key={s} className={filter===s?"chosen":""} onClick={()=>setFilter(s)}>{s==="All"?"All":statusLabels[s as Ticket["status"]]||s}</button>)}</div></div><div className="incident-list">{visible.slice(0,onDashboard?4:20).map((t,i)=><article className="incident-row" key={t.id} onClick={()=>setSelected(t.id)}><div className={`branch-symbol ${colors[i%colors.length]}`}>{t.initials.slice(0,2)}</div><div className="incident-copy"><div className="incident-name"><b>{t.branch}</b><span>{t.device.split(" · ")[0]}</span><small>{t.id}</small></div><p>{t.issue}</p><small>Submitted: {formatSubmitted(t.submitted_at||t.time)} · Contact: {t.person} · {t.device}</small>{view==="admin"&&<small className={`elapsed-time ${t.status==="Resolved"?"stopped":"running"}`}>Time to solve: {formatDuration(elapsedFor(t))}</small>}</div><div className="incident-state"><span className={`state ${t.status.toLowerCase().replace(" ","-")}`}>{statusLabels[t.status]}</span><button onClick={e=>{e.stopPropagation();setSelected(t.id)}}>{t.status==="Resolved"?"Review & Solved":"Review & Solve"}</button></div></article>)}{visible.length===0&&<div className="no-rows">No incidents match this view.</div>}</div><div className="panel-foot">Showing {Math.min(visible.length,onDashboard?4:20)} of {visible.length} incidents <button onClick={()=>setActive("Call & Incident Register")}>Open incident register <ArrowRight size={13}/></button></div></section>}
        {onRepairs&&view==="admin"&&<section className="work-panel repair-panel"><div className="work-head"><div><h2><Wrench size={14}/> HARDWARE RECEIVED FOR REPAIRING</h2>{!onDashboard&&<p>Workshop receipt, repair status and handover records</p>}</div><button onClick={()=>setActive("Hardware Workshop Log")}>View Hardware Log <ArrowRight size={13}/></button></div><div className="repair-list">{repairs.slice(0,onDashboard?5:30).map((r,i)=><article className="repair-row" key={r.id}><div className={`repair-symbol ${colors[(i+2)%colors.length]}`}><HardDrive size={16}/></div><div className="repair-copy"><b>{r.branch_name}</b><small className="serial">{r.serial_no||"S/N pending"}</small><p>{r.brand_model||r.device} — Issue: {r.reported_problem}</p><small>Received: {r.submitted_at?formatSubmitted(r.submitted_at):r.received_at} · by Mohabbot</small></div><div className="repair-action"><span className={`repair-status ${r.status.toLowerCase().replaceAll(" ","-")}`}>{r.status}</span>{r.status!=="Solved"&&<button onClick={()=>updateRepair(r.id,"Solved")}>Solve Repair</button>}</div></article>)}{repairs.length===0&&<div className="no-rows">No hardware is currently logged for repair. Use “Receive Hardware” to add an item.</div>}</div><div className="panel-foot">{repairs.length} workshop records </div></section>}
      </div>
      {onInventory&&<section className="secondary-panel"><h2>New Inventory Register</h2><p>Head Office items are tracked separately from branch hardware repair records.</p><div className="stock-cards">{inventoryGroups.map(group=><button type="button" className={`stock-card inventory-summary-card ${inventoryFilter===group.name?"selected":""}`} key={group.name} onClick={()=>setInventoryFilter(inventoryFilter===group.name?"":group.name)} aria-pressed={inventoryFilter===group.name}><Box size={19}/><b>{group.name}</b><strong>{group.available} / {group.total}</strong><span>{group.available} Available · {[...group.brands].join(", ")||"No model recorded"}</span></button>)}</div>{inventoryFilter&&<div className="inventory-filter-note">Showing “{inventoryFilter}” items <button type="button" onClick={()=>setInventoryFilter("")}>Show all items</button></div>}<div className="inventory-ledger"><div className="inventory-ledger-head"><div><h3>Head Office Inventory Ledger</h3><span>{headOfficeItems.length} received items · {inventoryAtZonal} remain at Zonal Office · {inventoryDeployed} deployed to branches</span></div></div><div className="inventory-table-wrap"><table className="inventory-table"><thead><tr><th>Item</th><th>Date Received</th><th>Received From</th><th>Brand &amp; Model</th><th>SL No. of Item</th><th>Status</th><th>Signature Received</th><th>Where Supplied</th><th>Date Supplied</th><th>Sign IT</th><th>Take Date</th><th>Remarks</th><th>Action</th></tr></thead><tbody>{visibleInventory.map(item=>{const atZonal=!item.where_supplied&&!['Issued to Branch','In Use'].includes(item.status);return <tr key={item.id} className={atZonal?"inventory-row-preserved":""}><td>{item.item}</td><td>{formatSubmitted(item.date_received)}</td><td>{item.received_from}</td><td>{item.brand_model}</td><td>{item.item_serial_no}</td><td>{atZonal?"Available at Zonal Office":item.status}</td><td>{item.signature_received}</td><td>{item.where_supplied}</td><td>{item.date_supplied}</td><td>{item.sign_it}</td><td>{item.take_date}</td><td>{item.remarks}</td><td>{atZonal&&<button className="btn-outline compact" onClick={()=>setDeployItem(item)}>Deploy</button>}</td></tr>})}</tbody></table>{visibleInventory.length===0&&<div className="no-rows">{headOfficeItems.length===0?"No Head Office items have been received yet. Use “Receive from Head office” to add the first item.":"No inventory items match this filter."}</div>}</div></div></section>}
      {active==="Forward Hardware to Zonal IT"&&<section className="secondary-panel"><h2>Forward Faulty Hardware to Zonal IT</h2><p>Submit the forwarding information for a problematic device sent from your branch to Rajshahi Zonal IT.</p><form className="forward-form" action={forwardHardware}><label>Branch Name<select name="branch_name" required defaultValue={auth.branchName||""}><option value="" disabled>Select a branch / sub-branch</option>{branches.map(branch=><option key={branch.code} value={branch.name}>{branchNames[branch.name]||branch.name}</option>)}</select></label><label>Date Time<input value={submitTime} readOnly/></label><div className="form-pair"><label>Device type<input name="device" required placeholder="Desktop / Printer / UPS"/></label><label>Brand &amp; model<input name="brand_model" placeholder="e.g. Dell OptiPlex"/></label></div><div className="form-pair"><label>Serial number<input name="serial_no" placeholder="Serial / service tag"/></label><label>Sender name<input name="sender" required placeholder="Name of person sending it"/></label></div><label>Fault description<textarea name="reported_problem" required rows={3} placeholder="Describe the problem and any checks already done…"/></label><button className="btn-navy"><Send size={14}/> Hardware Submit to Zonal IT</button></form><div className="repair-list branch-forward-list">{repairs.map(r=><article className="repair-row" key={r.id}><div className="repair-copy"><b>{r.branch_name} · {r.device} · {r.brand_model}</b><p>{r.reported_problem}</p><small>{r.submitted_at?formatSubmitted(r.submitted_at):r.received_at} · {r.status}</small></div></article>)}</div></section>}
      {active==="Requisition & Forms"&&<section className="secondary-panel requisition-panel"><h2>Requisition &amp; Forms</h2><p>Download the requisition template, complete it, and upload it here for Zonal IT.</p><div className="document-card"><FileText size={22}/><div><b>IT Hardware Requisition Form</b><span>CSV template · opens in Microsoft Excel</span></div><a className="btn-navy" href="/forms/IT-Hardware-Requisition-Form.csv" download><ArrowDownToLine size={15}/> Download Requisition</a></div><form className="requisition-upload" onSubmit={uploadRequisition}><div className="requisition-upload-copy"><b><FileText size={17}/> Upload and Submit Requisition</b><span>{view==="branch"?`Submitting for ${auth.branchName||"your branch"}; Zonal IT will receive it.`:"Upload a completed requisition or supporting form for branches."}</span></div><label>Form title<input name="title" maxLength={160} placeholder="e.g. Printer replacement requisition"/></label><label>Choose completed form<input name="file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.csv,.jpg,.jpeg,.png" required/></label><small>PDF, Word, Excel, CSV, JPG or PNG · Maximum 10 MB</small><button className="btn-navy" disabled={uploading}><Send size={14}/>{uploading?"Uploading…":"Upload and Submit Requisition"}</button></form><div className="uploaded-documents"><h3>Submitted Requisitions and Forms</h3>{documents.length===0?<div className="no-rows">No requisitions or forms have been uploaded yet.</div>:documents.map(doc=><article className="document-row" key={doc.id}><FileText size={19}/><div><b>{doc.title}</b><span>{doc.file_name} · {(doc.file_size/1024).toFixed(0)} KB</span><small>{doc.branch_name?`${branchNames[doc.branch_name]||doc.branch_name} · `:"Zonal IT · "}{doc.uploaded_by_name} · {formatSubmitted(doc.uploaded_at)}</small></div><a className="btn-outline" href={`/api/documents/${doc.id}`}><ArrowDownToLine size={14}/> Download</a></article>)}</div></section>}
      {active==="Report/Log Register"&&<section className="secondary-panel report-panel"><h2>Report/Log Register</h2><p>Choose a register and date range, then generate a printable or downloadable report.</p><div className="report-controls"><label>From <input type="date" value={reportFrom} max={reportTo} onChange={e=>{setReportFrom(e.target.value);setReportReady(false)}}/></label><label>To <input type="date" value={reportTo} min={reportFrom} onChange={e=>{setReportTo(e.target.value);setReportReady(false)}}/></label><button className="btn-navy" onClick={()=>setReportReady(true)}><Search size={15}/> Generate report</button>{reportReady&&<><button className="btn-navy" onClick={()=>window.print()}><Printer size={15}/> Print report</button><button className="btn-outline" onClick={exportSelectedReport}><ArrowDownToLine size={15}/> Export CSV</button></>}</div>{reportReady&&<><div className="report-print-head"><div className="report-print-brand"><Image src="/brand/islami-bank-emblem.png" alt="Islami Bank Bangladesh PLC" width={42} height={42}/><div><strong>ISLAMI BANK BANGLADESH PLC</strong><b>RAJSHAHI ZONE | ZONAL IT SUPPORT</b><span>REPORT / LOG REGISTER</span></div></div><div className="report-print-meta"><span><b>Business Unit:</b> Rajshahi Zonal IT Office</span><span><b>Report Period:</b> {reportFrom} to {reportTo}</span><span><b>Generated:</b> {localSubmitTime()}</span><span className="report-page-number">Page <i/></span></div></div><div className="report-summary"><span><b>{reportKind==="incidents"?reportTickets.length:reportKind==="repairs"?reportRepairs.length:reportInventory.length}</b> {reportKind==="incidents"?"Incident or problem records":reportKind==="repairs"?"Repair hardware records":"New inventory records"}</span><span>{reportFrom} — {reportTo}</span></div><div className="report-table-wrap">{reportKind==="incidents"?<table className="incident-report-table"><thead><tr><th>Ticket</th><th>User ID</th><th>Branch</th><th>Problem Type</th><th>Problem</th><th>Submit time</th><th>Status</th><th>Solver ID</th><th>Time to solve</th></tr></thead><tbody>{reportTickets.map(t=><tr key={t.id}><td>{t.id}</td><td>{t.user_id||"—"}</td><td>{t.branch}</td><td>{t.device}</td><td>{t.issue}</td><td>{formatSubmitted(t.submitted_at||t.time)}</td><td>{statusLabels[t.status]}</td><td>{t.solver_id||"—"}</td><td>{formatDuration(elapsedFor(t))}</td></tr>)}</tbody></table>:reportKind==="repairs"?<table className="incident-report-table"><thead><tr><th>Record ID</th><th>Branch</th><th>Device</th><th>Brand &amp; Model</th><th>Serial No.</th><th>Problem</th><th>Status</th><th>Date Time</th></tr></thead><tbody>{reportRepairs.map(r=><tr key={r.id}><td>{r.id}</td><td>{branchNames[r.branch_name]||r.branch_name}</td><td>{r.device}</td><td>{r.brand_model}</td><td>{r.serial_no}</td><td>{r.reported_problem}</td><td>{r.status}</td><td>{formatSubmitted(r.submitted_at||r.received_at)}</td></tr>)}</tbody></table>:<table className="inventory-table"><thead><tr>{["Item","Date Received","Received From","Brand & Model","SL No. of Item","Status","Signature Received","Where Supplied","Date Supplied","Sign IT","Take Date","Remarks"].map(head=><th key={head}>{head}</th>)}</tr></thead><tbody>{reportInventory.map(i=><tr key={i.id}><td>{i.item}</td><td>{formatSubmitted(i.date_received)}</td><td>{i.received_from}</td><td>{i.brand_model}</td><td>{i.item_serial_no}</td><td>{i.status}</td><td>{i.signature_received}</td><td>{i.where_supplied}</td><td>{i.date_supplied}</td><td>{i.sign_it}</td><td>{i.take_date}</td><td>{i.remarks}</td></tr>)}</tbody></table>}</div><div className="report-signatures"><span>Prepared By</span><span>Zonal IT In-charge</span><span>Manager Operation</span></div></>}</section>}
      <footer className="portal-footer"><span>© 2026 Islami Bank Bangladesh PLC · Rajshahi Zone</span><span><ShieldCheck size={13}/> Local Server: <b>Online</b></span></footer>
    </section>
    {notice&&<div className="toast"><Check size={16}/>{notice}<button onClick={()=>setNotice("")}><X size={14}/></button></div>}
    {selectedTicket&&<div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)setSelected(null)}}><section className="portal-modal"><div className="modal-head"><div><small className="ticket-id-label"><span className="ticket-id-number">{selectedTicket.id}</span><span className="ticket-id-separator"> · </span><span className="ticket-branch-name">{selectedTicket.branch}</span></small><h2>{selectedTicket.issue}</h2><p className="ticket-quick-info">{selectedTicket.device} · Reported by {selectedTicket.person}{view==="admin"&&selectedTicket.computer_ip?` · Computer IP: ${selectedTicket.computer_ip}`:""}</p>{view==="admin"&&selectedTicket.contact_phone&&<a className="ticket-contact-link" href={`tel:${selectedTicket.contact_phone}`}><Phone size={14}/>Call {selectedTicket.contact_phone}</a>}{view==="admin"&&<div className={`ticket-elapsed ${selectedTicket.status==="Resolved"?"stopped":"running"}`}><Clock3 size={15}/><span>{selectedTicket.status==="Resolved"?"Time to solve":"Elapsed since token generated"}</span><strong>{formatDuration(elapsedFor(selectedTicket))}</strong></div>}</div><button onClick={()=>setSelected(null)}><X size={18}/></button></div>{view==="admin"?<><label className="ticket-resolution-label">Resolution notes<textarea id="resolution-notes" rows={3} value={resolutionNotes} onChange={e=>setResolutionNotes(e.target.value)} placeholder="Describe the remote troubleshooting and resolution..."/></label><div className="modal-buttons"><button className="btn-outline" onClick={()=>updateTicket(selectedTicket.id,"Waiting")}>Wait for FRSD</button><button className="btn-navy" onClick={()=>updateTicket(selectedTicket.id,"Resolved")}><Check size={15}/> Mark Solved</button></div></>:<><div className="resolution-summary"><b>Current status: {statusLabels[selectedTicket.status]}</b><p>{selectedTicket.resolution_notes||"Zonal IT has not added resolution notes yet."}</p></div>{selectedTicket.status==="Resolved"&&<>{selectedTicket.satisfaction?<div className="feedback-thanks"><Check size={18}/><b>Thank you for your feedback.</b></div>:<><label>Feedback<textarea rows={3} value={feedbackNote} onChange={e=>setFeedbackNote(e.target.value)} placeholder="Tell us whether the issue is resolved or needs more support…"/></label><div className="modal-buttons"><button className="btn-outline" onClick={()=>submitFeedback(selectedTicket.id,false)}>Still having an issue</button><button className="btn-navy" onClick={()=>submitFeedback(selectedTicket.id,true)}><Check size={15}/> Solved, thank you</button></div></>}</>}</>}</section></div>}
    {ticketModal&&<div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)setTicketModal(false)}}><form className="portal-modal" action={saveTicket}><div className="modal-head"><div><small>{view==="branch"?"BRANCH SUPPORT":"PHONE CALL SUPPORT"}</small><h2>{view==="branch"?"Submit an IT Support Request":"Log Phone Call Incident"}</h2><p>{view==="branch"?"Record the issue and route it to zonal IT support.":"Enter the caller’s issue here so it is included in the same incident register."}</p></div><button type="button" onClick={()=>setTicketModal(false)}><X size={18}/></button></div><div className="ticket-context-grid">{view==="branch"?<><label>Login ID<input value={auth.username} readOnly/></label><input type="hidden" name="branch" value={auth.branchName||""}/><label>Branch / Sub-branch<input value={auth.branchName||"Assigned branch"} readOnly/></label></>:<><label>Branch / Sub-branch<select name="branch" required value={selectedBranch} onChange={e=>setSelectedBranch(e.target.value)}><option value="" disabled>Select a branch / sub-branch</option>{branches.map(branch=><option key={branch.code} value={branch.name}>{branchNames[branch.name]||branch.name}</option>)}</select></label><label>Login ID<input name="loginId" placeholder="Optional · enter caller’s login ID"/></label></>}<label>Submit time<input value={submitTime} readOnly/></label><label>Computer IP<input name="computerIp" placeholder="e.g. 192.168.1.25"/></label></div><div className="ticket-context-grid"><label>Contact<input name="contactPhone" type="tel" autoComplete="tel" placeholder="IP Phone / Personal Phone"/></label><label>Problem Type<select name="problemType"><option>Computer / Terminal</option><option>Network / Router</option><option>Printer</option><option>Scanner</option><option>Email / User Access</option><option>UPS</option><option>IP Phone</option></select></label></div><label>Issue description<textarea name="issue" rows={3} required placeholder="Describe the problem and affected terminal..."/></label><div className="modal-buttons"><button type="button" className="btn-outline" onClick={()=>setTicketModal(false)}>Cancel</button><button className="btn-navy"><Send size={14}/>{view==="branch"?"Problem Submit to Zonal IT":"Log Phone Call Incident"}</button></div></form></div>}
    {repairModal&&<div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)setRepairModal(false)}}><form className="portal-modal" action={saveRepair}><div className="modal-head"><div><small>WORKSHOP INTAKE</small><h2>Receive Hardware for Repair</h2><p>Register a branch hardware item and add it to the workshop log.</p></div><button type="button" onClick={()=>setRepairModal(false)}><X size={18}/></button></div><label>Branch Name<select name="branch_name" required value={selectedBranch} onChange={e=>setSelectedBranch(e.target.value)}><option value="" disabled>Select a branch / sub-branch</option>{branches.map(branch=><option key={branch.code} value={branch.name}>{branchNames[branch.name]||branch.name}</option>)}</select></label><label>Date Time<input value={submitTime} readOnly/></label><div className="form-pair"><label>Device type<input name="device" required placeholder="Desktop / Printer / UPS"/></label><label>Brand &amp; model<input name="brand_model" placeholder="e.g. Dell OptiPlex"/></label></div><div className="form-pair"><label>Serial number<input name="serial_no" placeholder="Serial / service tag"/></label><label>Sender name<input name="sender" required placeholder="Name of branch sender"/></label></div><label>Fault description<textarea name="reported_problem" required rows={3} placeholder="Describe the problem and any checks already done…"/></label><div className="modal-buttons"><button type="button" className="btn-outline" onClick={()=>setRepairModal(false)}>Cancel</button><button className="btn-coral"><Plus size={15}/> Receive hardware</button></div></form></div>}
    {stockModal&&<div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)setStockModal(false)}}><form className="portal-modal" action={issueStock}><div className="modal-head"><div><small>EMERGENCY REPLACEMENT</small><h2>Issue Buffer Stock</h2><p>The available count will decrease and an issue record will be saved.</p></div><button type="button" onClick={()=>setStockModal(false)}><X size={18}/></button></div><label>Available stock item<select name="stock_item_id" required>{stock.filter(item=>item.available_quantity>0).map(item=><option key={item.id} value={item.id}>{item.item_type} · {item.brand_model} · {item.available_quantity} available</option>)}</select></label><label>Receiving branch<input name="branch_name" required placeholder="Branch / Sub-branch"/></label><label>Faulty item being replaced<input name="faulty_item_details" placeholder="Item type, model or serial number"/></label><label>Handed over to<input name="issued_to" placeholder="Branch contact name"/></label><div className="modal-buttons"><button type="button" className="btn-outline" onClick={()=>setStockModal(false)}>Cancel</button><button className="btn-navy"><Send size={14}/> Issue stock</button></div></form></div>}
    {headOfficeModal&&<div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)setHeadOfficeModal(false)}}><form className="portal-modal head-office-modal" action={saveHeadOfficeItem}><div className="modal-head"><div><small>HEAD OFFICE INVENTORY</small><h2>Receive from Head office</h2><p>Record the receipt in the separate Head Office inventory ledger.</p></div><button type="button" onClick={()=>setHeadOfficeModal(false)}><X size={18}/></button></div><label>Item<input name="item" required placeholder="e.g. Router" autoFocus/></label><label>Date of Received<input value={submitTime} readOnly/></label><label>Received from<input name="received_from" defaultValue="Head Office" required/></label><div className="form-pair"><label>Brand &amp; Model<input name="brand_model" placeholder="e.g. MikroTik RB2011"/></label><label>SL No. of Item<input name="item_serial_no" placeholder="Serial number"/></label></div><label>Status<select name="status" defaultValue="New"><option>New</option><option>Available</option><option>Issued to Branch</option><option>In Use</option><option>Returned</option><option>Other</option></select></label><div className="form-pair"><label>Signature Received<input name="signature_received" placeholder="Received by"/></label><label>Where Supplied<input name="where_supplied" placeholder="Branch / Sub-branch"/></label></div><div className="form-pair"><label>Date Supplied<input name="date_supplied" type="date"/></label><label>Sign IT<input name="sign_it" placeholder="IT staff name / signature"/></label></div><label>Take Date<input name="take_date" type="date"/></label><label>Remarks<textarea name="remarks" rows={2} placeholder="Additional notes"/></label><div className="modal-buttons"><button type="button" className="btn-outline" onClick={()=>setHeadOfficeModal(false)}>Cancel</button><button className="btn-coral"><Plus size={15}/> Receive from Head office</button></div></form></div>}
    {deployItem&&<div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)setDeployItem(null)}}><form className="portal-modal" action={deployHeadOfficeItem}><div className="modal-head"><div><small>NEW INVENTORY DEPLOYMENT</small><h2>Deploy {deployItem.item}</h2><p>This item will move from Zonal Office stock to the selected branch.</p></div><button type="button" onClick={()=>setDeployItem(null)}><X size={18}/></button></div><label>Branch / Sub-branch<select name="where_supplied" required defaultValue=""><option value="" disabled>Select a branch / sub-branch</option>{branches.map(branch=><option key={branch.code} value={branch.name}>{branchNames[branch.name]||branch.name}</option>)}</select></label><label>Take Date<input name="take_date" type="date" defaultValue={dhakaDate()}/></label><label>Sign IT<input name="sign_it" defaultValue={auth.name} required/></label><label>Remarks<textarea name="remarks" rows={2} placeholder="Deployment notes"/></label><div className="modal-buttons"><button type="button" className="btn-outline" onClick={()=>setDeployItem(null)}>Cancel</button><button className="btn-navy"><Send size={14}/> Confirm Deployment</button></div></form></div>}
  </main>;
}

function Metric({icon:Icon,title,value,note,color,onClick}:{icon:LucideIcon;title:string;value:string;note:string;color:string;onClick:()=>void}){return <button type="button" className="metric-card" onClick={onClick}><span className={`metric-icon ${color}`}><Icon size={21}/></span><div><small>{title}</small><strong className={color}>{value}</strong><span>{note}</span></div></button>}

function LoginScreen({onLogin}:{onLogin:(user:PortalUser)=>void}){
  const [role,setRole]=useState<"branch_user"|"zonal_staff">("branch_user");const [username,setUsername]=useState("");const [password,setPassword]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [branches,setBranches]=useState<{code:string;name:string;kind:string}[]>([]);const [branchCode,setBranchCode]=useState("");
  useEffect(()=>{fetch("/api/branches").then(r=>r.ok?r.json():[]).then((rows:{code:string;name:string;kind:string}[])=>{setBranches(rows);setBranchCode(rows[0]?.code||"")}).catch(()=>setBranches([]))},[]);
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError("");try{const response=await fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username,password,role,branchCode})});const data=await response.json();if(!response.ok){setError(data.error||"Sign in failed.");return;}onLogin(data.user);}catch{setError("Portal server is not reachable.");}finally{setBusy(false)}};
  return <main className="login-page"><div className="login-card"><div className="login-brand"><Image src="/brand/islami-bank-emblem.png" alt="Islami Bank" width={52} height={52}/><div><b>Islami Bank Bangladesh PLC</b><span>Rajshahi Zonal IT Support Portal</span></div></div><h1>Sign in to the portal</h1><p className="login-subtitle">Choose your account type to continue. Branch registration is not required.</p><div className="login-tabs"><button type="button" className={role==="branch_user"?"selected":""} onClick={()=>{setRole("branch_user");setError("")}}><Building2 size={16}/> Branch User</button><button type="button" className={role==="zonal_staff"?"selected":""} onClick={()=>{setRole("zonal_staff");setError("")}}><ShieldCheck size={16}/> Zonal IT</button></div><form onSubmit={submit}>{role==="branch_user"&&<label>Select Branch / Sub-branch<select required value={branchCode} onChange={e=>setBranchCode(e.target.value)}><option value="" disabled>Select your branch</option>{branches.map(b=><option key={b.code} value={b.code}>{branchNames[b.name]||b.name}</option>)}</select></label>}<label>Portal User ID<input required autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} placeholder="e.g. kader211931"/></label><label>Portal Password<input required type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your portal password"/></label>{error&&<div className="login-error">{error}</div>}<button className="login-submit" disabled={busy|| (role==="branch_user"&&!branchCode)}>{busy?"Signing in…":"Sign in securely"}<ArrowRight size={16}/></button></form><div className="login-note"><LockKeyhole size={14}/><span>Use your assigned portal password. This prototype checks its own account records.</span></div><p className="login-help">For access assistance, contact Rajshahi Zonal IT.</p></div><footer className="login-footer">Rajshahi Zone · Internal IT Support</footer></main>
}



